<?php class AuthController extends Controller{
 function login(){$this->view('auth/login');} function patientRegister(){$this->view('auth/patient_register');} function doctorRegister(){$db=Database::db();$this->view('auth/doctor_register',['specializations'=>$db->query('SELECT * FROM specializations ORDER BY name')->fetchAll(PDO::FETCH_ASSOC),'hospitals'=>$db->query('SELECT * FROM hospitals WHERE status="active" ORDER BY name')->fetchAll(PDO::FETCH_ASSOC)]);}
 function authenticate(){$db=Database::db();$role=$_POST['login_as']??'';$allowed=['super_admin','doctor','patient'];if(!in_array($role,$allowed,true)){$this->view('auth/login',['error'=>'Please select Admin, Doctor or Patient.']);return;}$q=$db->prepare('SELECT users.*,roles.name role_name FROM users JOIN roles ON roles.id=users.role_id WHERE (users.email=? OR users.phone=?) AND roles.name=? AND users.status="active"');$id=trim($_POST['identity']??'');$q->execute([$id,$id,$role]);$u=$q->fetch(PDO::FETCH_ASSOC);if($u&&password_verify($_POST['password']??'',$u['password'])){$_SESSION['user']=$u;$this->go('/dashboard');}$this->view('auth/login',['error'=>'Invalid credentials, wrong login type, or account is not active.']);}
 private function validPass($x){return strlen($x)>=8&&preg_match('/[A-Z]/',$x)&&preg_match('/[a-z]/',$x)&&preg_match('/\d/',$x)&&preg_match('/[^A-Za-z0-9]/',$x);}
 function storePatient(){$db=Database::db();$pw=$_POST['password']??'';if($pw!==($_POST['confirm_password']??'')||!$this->validPass($pw)){$this->view('auth/patient_register',['error'=>'Password does not meet the required rules or confirmation does not match.']);return;}try{$db->beginTransaction();$rid=$db->query("SELECT id FROM roles WHERE name='patient'")->fetchColumn();$q=$db->prepare('INSERT INTO users(role_id,name,email,phone,aadhaar_no,pan_no,password,status) VALUES(?,?,?,?,?,?,?,"active")');$q->execute([$rid,$_POST['name'],$_POST['email'],$_POST['phone'],$_POST['aadhaar_no'],strtoupper($_POST['pan_no']??''),password_hash($pw,PASSWORD_DEFAULT)]);$uid=$db->lastInsertId();$photo=$this->uploadPhoto($uid);if($photo)$db->prepare('UPDATE users SET photo=? WHERE id=?')->execute([$photo,$uid]);$this->saveAddress($db,$uid);$db->prepare('INSERT INTO patient_profiles(user_id,dob,gender,blood_group,emergency_contact_name,emergency_contact_phone) VALUES(?,?,?,?,?,?)')->execute([$uid,$_POST['dob']?:null,$_POST['gender']?:null,$_POST['blood_group']?:null,$_POST['emergency_contact_name']?:null,$_POST['emergency_contact_phone']?:null]);$db->commit();$this->go('/login');}catch(Throwable $e){if($db->inTransaction())$db->rollBack();$this->view('auth/patient_register',['error'=>'Registration failed: '.$e->getMessage()]);}}
 function storeDoctor(){$db=Database::db();$pw=$_POST['password']??'';if($pw!==($_POST['confirm_password']??'')||!$this->validPass($pw)){$_SESSION['flash']='Password rules not met.';$this->go('/doctor/register');}try{$db->beginTransaction();$rid=$db->query("SELECT id FROM roles WHERE name='doctor'")->fetchColumn();$db->prepare('INSERT INTO users(role_id,name,email,phone,aadhaar_no,pan_no,password,status) VALUES(?,?,?,?,?,?,?,"pending")')->execute([$rid,$_POST['name'],$_POST['email'],$_POST['phone'],$_POST['aadhaar_no'],strtoupper($_POST['pan_no']??''),password_hash($pw,PASSWORD_DEFAULT)]);$uid=$db->lastInsertId();$photo=$this->uploadPhoto($uid);if($photo)$db->prepare('UPDATE users SET photo=? WHERE id=?')->execute([$photo,$uid]);$this->saveAddress($db,$uid);$db->prepare('INSERT INTO doctors(user_id,specialization_id,medical_registration_no,registration_council,experience_years,bio,verification_status) VALUES(?,?,?,?,?,?,"pending")')->execute([$uid,$_POST['specialization_id'],$_POST['medical_registration_no'],$_POST['registration_council'],$_POST['experience_years']?:0,$_POST['bio']]);$did=$db->lastInsertId();if(!empty($_POST['degree']))$db->prepare('INSERT INTO doctor_qualifications(doctor_id,degree,institute,university,passing_year,degree_number) VALUES(?,?,?,?,?,?)')->execute([$did,$_POST['degree'],$_POST['institute'],$_POST['university'],$_POST['passing_year']?:null,$_POST['degree_number']]);if(!empty($_POST['hospital_id']))$db->prepare('INSERT INTO doctor_hospitals(doctor_id,hospital_id,is_primary,consultation_fee,video_fee,emergency_fee) VALUES(?,?,1,?,?,?)')->execute([$did,$_POST['hospital_id'],$_POST['consultation_fee']?:0,$_POST['video_fee']?:0,$_POST['emergency_fee']?:0]);$db->commit();$_SESSION['flash']='Doctor registration submitted. Super Admin verification is required before login/public listing.';$this->go('/login');}catch(Throwable $e){if($db->inTransaction())$db->rollBack();$_SESSION['flash']='Registration failed: '.$e->getMessage();$this->go('/doctor/register');}}
 private function uploadPhoto($uid){if(empty($_FILES['photo']['name'])||$_FILES['photo']['error']!==UPLOAD_ERR_OK)return null;$ext=strtolower(pathinfo($_FILES['photo']['name'],PATHINFO_EXTENSION));if(!in_array($ext,['jpg','jpeg','png','webp']))return null;$dir=__DIR__.'/../../uploads/profiles';if(!is_dir($dir))mkdir($dir,0775,true);$name='user_'.$uid.'_'.time().'.'.$ext;move_uploaded_file($_FILES['photo']['tmp_name'],$dir.'/'.$name);return 'uploads/profiles/'.$name;}
 private function saveAddress($db,$uid){$db->prepare('INSERT INTO addresses(user_id,addressable_type,addressable_id,address_line1,address_line2,pincode,city,state,country) VALUES(?,"user",?,?,?,?,?,?,?)')->execute([$uid,$uid,$_POST['address_line1'],$_POST['address_line2'],$_POST['pincode'],$_POST['city'],$_POST['state'],$_POST['country']?:'India']);}
 function logout(){session_destroy();$this->go('/');}
}